import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";
import { SpriteManager, UnitAssets } from "../sprites";

// --- ECS COMPONENTS ---

/** 物理組件：負責空間座標與動力學積算 */
export interface PhysicsComponent {
    x: number; y: number; z: number;
    vx: number; vy: number; vz: number;
    angle: number; vAngle: number;
    px: number; py: number; // 邏輯世界座標 (Logical Ground)
}

/** 視覺組件：負責美術資源、動畫狀態與殘影緩存 */
export interface VisualComponent {
    assets: UnitAssets | null;
    animState: AnimState;
    visualStatus: 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';
    facing: number;
    hitFlashTimer: number;
    spawnTimer: number;
    trailHistory: {x: number, y: number, z: number}[];
}

/** 數值組件：負責生命週期與戰鬥屬性 */
export interface StatsComponent {
    hp: number; maxHp: number;
    mp: number; maxMp: number;
    shield: number; maxShield: number;
    weight: number; jump: number;
    moveSpeed: number; moveSpeedMult: number;
    movementType: MovementType;
}

/** 狀態組件：負責 CC 效果與 DR 衰減 */
export interface StatusComponent {
    stun: { timer: number, max: number };
    banish: { timer: number, max: number, active: boolean };
    silence: { timer: number, max: number };
    root: number; fear: number; taunt: number; blind: number;
    tauntTargetId: string | null;
    dot: { timer: number, dmg: number };
    hot: { timer: number, val: number };
    drStacks: Record<string, number>;
    drTimers: Record<string, number>;
}

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;

    // ECS Components
    public physics: PhysicsComponent;
    public visual: VisualComponent;
    public stats: StatsComponent;
    public status: StatusComponent;

    // AI & Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public curCDs: number[] = [0, 0, 0];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;

    public bt: BTNode | null = null;
    public btStatus: string = "待機";
    public target: Agent | null = null;
    public targetHex: Hex | null = null;
    public isMoving: boolean = false;
    public path: Hex[] = [];
    public trajectory: Hex[] = [];
    public moveProgress: number = 0;

    public fullyDead: boolean = false;
    public deadLogged: boolean = false;

    public initialState: any;

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR;
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);

        // 初始化物理組件 (Physics SSOT)
        this.physics = {
            x: 0, y: 0, z: 0,
            vx: 0, vy: 0, vz: 0,
            angle: 0, vAngle: 0,
            px: p.x, py: p.y
        };

        // 初始化視覺組件 (Visual ECS)
        this.visual = {
            assets: null,
            animState: AnimState.IDLE,
            visualStatus: 'NONE',
            facing: team === Team.BLUE ? 1 : -1,
            hitFlashTimer: 0,
            spawnTimer: 0.5,
            trailHistory: []
        };

        // 初始化數值組件
        this.stats = {
            hp: 100, maxHp: 100,
            mp: 0, maxMp: 100,
            shield: 0, maxShield: 0,
            weight: 1, jump: 1,
            moveSpeed: 1, moveSpeedMult: 1,
            movementType: MovementType.GROUND
        };

        // 初始化狀態組件
        this.status = {
            stun: { timer: 0, max: 0 },
            banish: { timer: 0, max: 0, active: false },
            silence: { timer: 0, max: 0 },
            root: 0, fear: 0, taunt: 0, blind: 0,
            tauntTargetId: null,
            dot: { timer: 0, dmg: 0 },
            hot: { timer: 0, val: 0 },
            drStacks: {},
            drTimers: {}
        };
    }

    /** 核心資源同步：按職業與陣營刷新 ECS 資源 */
    public refreshAssets() {
        this.visual.assets = SpriteManager.getUnitImages(this.role, this.team);
    }

    /** Legacy Compatibility Getters (避免大規模破壞系統) */
    get hp() { return this.stats.hp; }
    set hp(v) { this.stats.hp = v; }
    get maxHp() { return this.stats.maxHp; }
    set maxHp(v) { this.stats.maxHp = v; }
    get mp() { return this.stats.mp; }
    set mp(v) { this.stats.mp = v; }
    get maxMp() { return this.stats.maxMp; }
    set maxMp(v) { this.stats.maxMp = v; }
    get shield() { return this.stats.shield; }
    set shield(v) { this.stats.shield = v; }
    get maxShield() { return this.stats.maxShield; }
    set maxShield(v) { this.stats.maxShield = v; }
    get px() { return this.physics.px; }
    set px(v) { this.physics.px = v; }
    get py() { return this.physics.py; }
    set py(v) { this.physics.py = v; }
    get facing() { return this.visual.facing; }
    set facing(v) { this.visual.facing = v; }
    get animState() { return this.visual.animState; }
    set animState(v) { this.visual.animState = v; }
    get visualStatus() { return this.visual.visualStatus; }
    set visualStatus(v) { this.visual.visualStatus = v; }
    get hitFlashTimer() { return this.visual.hitFlashTimer; }
    set hitFlashTimer(v) { this.visual.hitFlashTimer = v; }
    get spawnTimer() { return this.visual.spawnTimer; }
    set spawnTimer(v) { this.visual.spawnTimer = v; }
    get jump() { return this.stats.jump; }
    set jump(v) { this.stats.jump = v; }
    get weight() { return this.stats.weight; }
    set weight(v) { this.stats.weight = v; }
    get moveSpeed() { return this.stats.moveSpeed; }
    set moveSpeed(v) { this.stats.moveSpeed = v; }
    get moveSpeedMult() { return this.stats.moveSpeedMult; }
    set moveSpeedMult(v) { this.stats.moveSpeedMult = v; }
    get movementType() { return this.stats.movementType; }
    set movementType(v) { this.stats.movementType = v; }
    get trailHistory() { return this.visual.trailHistory; }
    set trailHistory(v) { this.visual.trailHistory = v; }

    /** 改良型狀態計時器訪問器 */
    get stunTimer() { return this.status.stun.timer; }
    set stunTimer(v) { this.status.stun.timer = v; }
    get stunMax() { return this.status.stun.max; }
    set stunMax(v) { this.status.stun.max = v; }
    get banishTimer() { return this.status.banish.timer; }
    set banishTimer(v) { this.status.banish.timer = v; }
    get banishMax() { return this.status.banish.max; }
    set banishMax(v) { this.status.banish.max = v; }
    get banished() { return this.status.banish.active; }
    set banished(v) { this.status.banish.active = v; }
    get silenceTimer() { return this.status.silence.timer; }
    set silenceTimer(v) { this.status.silence.timer = v; }
    get silenceMax() { return this.status.silence.max; }
    set silenceMax(v) { this.status.silence.max = v; }
    get rootTimer() { return this.status.root; }
    set rootTimer(v) { this.status.root = v; }
    get fearTimer() { return this.status.fear; }
    set fearTimer(v) { this.status.fear = v; }
    get tauntTimer() { return this.status.taunt; }
    set tauntTimer(v) { this.status.taunt = v; }
    get blindTimer() { return this.status.blind; }
    set blindTimer(v) { this.status.blind = v; }
    get tauntTargetId() { return this.status.tauntTargetId; }
    set tauntTargetId(v) { this.status.tauntTargetId = v; }
    get dotTimer() { return this.status.dot.timer; }
    set dotTimer(v) { this.status.dot.timer = v; }
    get dotDmg() { return this.status.dot.dmg; }
    set dotDmg(v) { this.status.dot.dmg = v; }
    get hotTimer() { return this.status.hot.timer; }
    set hotTimer(v) { this.status.hot.timer = v; }
    get hotVal() { return this.status.hot.val; }
    set hotVal(v) { this.status.hot.val = v; }
    get drStacks() { return this.status.drStacks; }
    get drTimers() { return this.status.drTimers; }

    public setAnim(state: AnimState) {
        if (this.visual.animState !== state && this.visual.animState !== AnimState.DEAD) {
            this.visual.animState = state;
        }
    }

    public saveState() {
        this.initialState = {
            q: this.q, r: this.r,
            maxHp: this.stats.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    public reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);

        this.physics.px = p.x;
        this.physics.py = p.y;
        this.physics.x = this.physics.y = this.physics.z = 0;
        this.physics.vx = this.physics.vy = this.physics.vz = 0;
        this.physics.angle = this.physics.vAngle = 0;

        this.role = this.initialState.role;
        const stats = UNIT_DB[this.role];
        if (stats) {
            this.stats.maxHp = this.initialState.maxHp;
            this.stats.hp = this.stats.maxHp;
            this.stats.mp = 0;
            this.stats.maxMp = stats.maxMp;
            this.stats.moveSpeed = stats.moveSpeed;
            this.stats.moveSpeedMult = 1.0;
            this.stats.jump = stats.jump;
            this.stats.weight = stats.weight;
            this.stats.movementType = stats.movementType;
            this.stats.shield = 0;
            this.stats.maxShield = 0;
        }

        this.visual.animState = AnimState.IDLE;
        this.visual.visualStatus = 'NONE';
        this.visual.hitFlashTimer = 0;
        this.visual.spawnTimer = 0.5;
        this.visual.trailHistory = [];
        this.visual.facing = this.team === Team.BLUE ? 1 : -1;

        this.status.stun = { timer: 0, max: 0 };
        this.status.banish = { timer: 0, max: 0, active: false };
        this.status.silence = { timer: 0, max: 0 };
        this.status.root = this.status.fear = this.status.taunt = this.status.blind = 0;
        this.status.dot = { timer: 0, dmg: 0 };
        this.status.hot = { timer: 0, val: 0 };
        this.status.drStacks = {};
        this.status.drTimers = {};

        this.skillIds = [...this.initialState.skillIds];
        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.path = [];
        this.moveProgress = 0;
        this.target = null;
        this.targetHex = null;
        this.fullyDead = false;
        this.deadLogged = false;

        this.refreshAssets();
    }
}

import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { FACTION_VISUALS } from "../../data/vfx/faction_visuals";

export class AgentManager {
    /**
     * 新增單位：支持強制職業注入
     */
    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number, forceRole?: Role): Agent | null {
        // 防止在地圖外或障礙物上生成
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);

        // 職業選擇：如果沒有強制指定，則隨機
        const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        a.role = forceRole || allRoles[Math.floor(Math.random() * allRoles.length)];

        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        // 元件初始化
        const stats = UNIT_DB[a.role];
        a.stats.maxHp = hpOverride || stats.maxHp;
        a.stats.hp = a.stats.maxHp;
        a.stats.maxMp = stats.maxMp;
        a.stats.moveSpeed = stats.moveSpeed; 
        a.stats.movementType = stats.movementType;
        a.stats.jump = stats.jump;
        a.stats.weight = stats.weight;

        // 技能匹配
        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rndS = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rndS(validSkills.filter(s => s.tag === 'ULT')),
            rndS(validSkills.filter(s => s.tag === 'ACTIVE')),
            rndS(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        const visual = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];
        a.visual.spawnTimer = 0.5;
        a.refreshAssets(); // 關鍵：ECS 資源掛載

        engine.events.push({ type: 'SPAWN', pos: { x: a.physics.px, y: a.physics.py }, color: visual.primaryColor, sourceId: a.id });

        if (engine.isRunning) {
            a.skills = a.skillIds.map(id => engine.skillDB.find(s => s.id === id) || null);
            a.bt = engine.ai.buildAI(a, engine);
            a.visual.animState = AnimState.IDLE;
        }

        engine.agents.push(a);
        engine.map.registerAgent(a);
        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;
        if (!a.deadLogged) {
            engine.log(a, 'DEATH', '死亡', null, '陣亡');
            engine.events.push({ type: 'DEATH', pos: {x: a.physics.px, y: a.physics.py}, sourceId: a.id, team: a.team });
            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);

            engine.map.unregisterAgent(a);

            a.fullyDead = true; 
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);

    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => engine.bus.off('GAME_OVER', handleGameOver);
    }, []);

    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    /** 核心優化：職業平衡生成器 (Balanced 5VS5) */
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        // 洗牌算法
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;

        const spawnTeam = (team: Team) => {
            roles.forEach(role => {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    const hp = 600 + Math.floor(Math.random() * 400); 
                    engine.addAgent(team, h.q, h.r, hp, role);
                }
            });
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);

        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    useEffect(() => {
        const interval = setInterval(() => setUnitCount(engineRef.current.agents.length), 500); 
        return () => clearInterval(interval);
    }, []);

    useEffect(() => { engineRef.current.timeScale = timeScale; }, [timeScale]);

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w); setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null); setWinner(null);
    }, []);

    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null); setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    /** 核心優化：隨機戰場亦套用職業平衡 */
    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null); setSelectedAgent(null);
        engine.clear(false); 

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w); setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIdx = 0;
        const spawnTeam = (team: Team) => {
            roles.forEach(role => {
                if (spawnIdx < validHexes.length) {
                    const h = validHexes[spawnIdx++];
                    engine.addAgent(team, h.q, h.r, 800, role);
                }
            });
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);
        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => setSelectedAgent(a);

    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode, handleUpdateMapSize, handleUpdateLayout, handleSetScene,
            handleRandomBattlefield, handleNextLevel, handleReset, togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent, startShowcaseMatch, downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        // --- ECS RESOURCE CHECK ---
        if (!agent.visual.assets) {
            agent.refreshAssets();
            if (!agent.visual.assets) return;
        }

        ctx.save(); 

        // 1. Transform to Body Center (Standard Anchor via VisualMath)
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 2. SCALE ADJUSTMENT
        ctx.scale(UNIT_SCALE, UNIT_SCALE);
        ctx.rotate(agent.physics.angle); 

        // 3. Animation Bobbing
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 4. Spawn Animation
        if (agent.visual.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.visual.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 5. Status Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.visual.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        // 6. Flight VFX
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visual.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        // 7. Facing Flip
        ctx.scale(agent.visual.facing > 0 ? 1 : -1, 1);

        // 8. Render Model
        if (agent.visual.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (agent.visual.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";
import { SpriteManager, UnitAssets } from "../sprites";

// --- ECS COMPONENTS ---

/** 物理組件：負責空間座標與動力學積算 */
export interface PhysicsComponent {
    x: number; y: number; z: number;
    vx: number; vy: number; vz: number;
    angle: number; vAngle: number;
    px: number; py: number; // 邏輯世界座標 (Logical Ground)
}

/** 視覺組件：負責美術資源、動畫狀態與殘影緩存 */
export interface VisualComponent {
    assets: UnitAssets | null;
    animState: AnimState;
    visualStatus: 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';
    facing: number;
    hitFlashTimer: number;
    spawnTimer: number;
    trailHistory: {x: number, y: number, z: number}[];
}

/** 數值組件：負責生命週期與戰鬥屬性 */
export interface StatsComponent {
    hp: number; maxHp: number;
    mp: number; maxMp: number;
    shield: number; maxShield: number;
    weight: number; jump: number;
    moveSpeed: number; moveSpeedMult: number;
    movementType: MovementType;
}

/** 狀態組件：負責 CC 效果與 DR 衰減 */
export interface StatusComponent {
    stun: { timer: number, max: number };
    banish: { timer: number, max: number, active: boolean };
    silence: { timer: number, max: number };
    root: number; fear: number; taunt: number; blind: number;
    tauntTargetId: string | null;
    dot: { timer: number, dmg: number };
    hot: { timer: number, val: number };
    drStacks: Record<string, number>;
    drTimers: Record<string, number>;
}

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;

    // ECS Components
    public physics: PhysicsComponent;
    public visual: VisualComponent;
    public stats: StatsComponent;
    public status: StatusComponent;

    // AI & Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public curCDs: number[] = [0, 0, 0];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;

    public bt: BTNode | null = null;
    public btStatus: string = "待機";
    public target: Agent | null = null;
    public targetHex: Hex | null = null;
    public isMoving: boolean = false;
    public path: Hex[] = [];
    public trajectory: Hex[] = [];
    public moveProgress: number = 0;

    public fullyDead: boolean = false;
    public deadLogged: boolean = false;

    public initialState: any;

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR;
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);

        // 初始化物理組件 (Physics SSOT)
        this.physics = {
            x: 0, y: 0, z: 0,
            vx: 0, vy: 0, vz: 0,
            angle: 0, vAngle: 0,
            px: p.x, py: p.y
        };

        // 初始化視覺組件 (Visual ECS)
        this.visual = {
            assets: null,
            animState: AnimState.IDLE,
            visualStatus: 'NONE',
            facing: team === Team.BLUE ? 1 : -1,
            hitFlashTimer: 0,
            spawnTimer: 0.5,
            trailHistory: []
        };

        // 初始化數值組件
        this.stats = {
            hp: 100, maxHp: 100,
            mp: 0, maxMp: 100,
            shield: 0, maxShield: 0,
            weight: 1, jump: 1,
            moveSpeed: 1, moveSpeedMult: 1,
            movementType: MovementType.GROUND
        };

        // 初始化狀態組件
        this.status = {
            stun: { timer: 0, max: 0 },
            banish: { timer: 0, max: 0, active: false },
            silence: { timer: 0, max: 0 },
            root: 0, fear: 0, taunt: 0, blind: 0,
            tauntTargetId: null,
            dot: { timer: 0, dmg: 0 },
            hot: { timer: 0, val: 0 },
            drStacks: {},
            drTimers: {}
        };
    }

    /** 核心資源同步：按職業與陣營刷新 ECS 資源 */
    public refreshAssets() {
        this.visual.assets = SpriteManager.getUnitImages(this.role, this.team);
    }

    /** Legacy Compatibility Getters (避免大規模破壞系統) */
    get hp() { return this.stats.hp; }
    set hp(v) { this.stats.hp = v; }
    get maxHp() { return this.stats.maxHp; }
    set maxHp(v) { this.stats.maxHp = v; }
    get mp() { return this.stats.mp; }
    set mp(v) { this.stats.mp = v; }
    get maxMp() { return this.stats.maxMp; }
    set maxMp(v) { this.stats.maxMp = v; }
    get shield() { return this.stats.shield; }
    set shield(v) { this.stats.shield = v; }
    get maxShield() { return this.stats.maxShield; }
    set maxShield(v) { this.stats.maxShield = v; }
    get px() { return this.physics.px; }
    set px(v) { this.physics.px = v; }
    get py() { return this.physics.py; }
    set py(v) { this.physics.py = v; }
    get facing() { return this.visual.facing; }
    set facing(v) { this.visual.facing = v; }
    get animState() { return this.visual.animState; }
    set animState(v) { this.visual.animState = v; }
    get visualStatus() { return this.visual.visualStatus; }
    set visualStatus(v) { this.visual.visualStatus = v; }
    get hitFlashTimer() { return this.visual.hitFlashTimer; }
    set hitFlashTimer(v) { this.visual.hitFlashTimer = v; }
    get spawnTimer() { return this.visual.spawnTimer; }
    set spawnTimer(v) { this.visual.spawnTimer = v; }
    get jump() { return this.stats.jump; }
    set jump(v) { this.stats.jump = v; }
    get weight() { return this.stats.weight; }
    set weight(v) { this.stats.weight = v; }
    get moveSpeed() { return this.stats.moveSpeed; }
    set moveSpeed(v) { this.stats.moveSpeed = v; }
    get moveSpeedMult() { return this.stats.moveSpeedMult; }
    set moveSpeedMult(v) { this.stats.moveSpeedMult = v; }
    get movementType() { return this.stats.movementType; }
    set movementType(v) { this.stats.movementType = v; }
    get trailHistory() { return this.visual.trailHistory; }
    set trailHistory(v) { this.visual.trailHistory = v; }

    /** 改良型狀態計時器訪問器 */
    get stunTimer() { return this.status.stun.timer; }
    set stunTimer(v) { this.status.stun.timer = v; }
    get stunMax() { return this.status.stun.max; }
    set stunMax(v) { this.status.stun.max = v; }
    get banishTimer() { return this.status.banish.timer; }
    set banishTimer(v) { this.status.banish.timer = v; }
    get banishMax() { return this.status.banish.max; }
    set banishMax(v) { this.status.banish.max = v; }
    get banished() { return this.status.banish.active; }
    set banished(v) { this.status.banish.active = v; }
    get silenceTimer() { return this.status.silence.timer; }
    set silenceTimer(v) { this.status.silence.timer = v; }
    get silenceMax() { return this.status.silence.max; }
    set silenceMax(v) { this.status.silence.max = v; }
    get rootTimer() { return this.status.root; }
    set rootTimer(v) { this.status.root = v; }
    get fearTimer() { return this.status.fear; }
    set fearTimer(v) { this.status.fear = v; }
    get tauntTimer() { return this.status.taunt; }
    set tauntTimer(v) { this.status.taunt = v; }
    get blindTimer() { return this.status.blind; }
    set blindTimer(v) { this.status.blind = v; }
    get tauntTargetId() { return this.status.tauntTargetId; }
    set tauntTargetId(v) { this.status.tauntTargetId = v; }
    get dotTimer() { return this.status.dot.timer; }
    set dotTimer(v) { this.status.dot.timer = v; }
    get dotDmg() { return this.status.dot.dmg; }
    set dotDmg(v) { this.status.dot.dmg = v; }
    get hotTimer() { return this.status.hot.timer; }
    set hotTimer(v) { this.status.hot.timer = v; }
    get hotVal() { return this.status.hot.val; }
    set hotVal(v) { this.status.hot.val = v; }
    get drStacks() { return this.status.drStacks; }
    get drTimers() { return this.status.drTimers; }

    public setAnim(state: AnimState) {
        if (this.visual.animState !== state && this.visual.animState !== AnimState.DEAD) {
            this.visual.animState = state;
        }
    }

    public saveState() {
        this.initialState = {
            q: this.q, r: this.r,
            maxHp: this.stats.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    public reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);

        this.physics.px = p.x;
        this.physics.py = p.y;
        this.physics.x = this.physics.y = this.physics.z = 0;
        this.physics.vx = this.physics.vy = this.physics.vz = 0;
        this.physics.angle = this.physics.vAngle = 0;

        this.role = this.initialState.role;
        const stats = UNIT_DB[this.role];
        if (stats) {
            this.stats.maxHp = this.initialState.maxHp;
            this.stats.hp = this.stats.maxHp;
            this.stats.mp = 0;
            this.stats.maxMp = stats.maxMp;
            this.stats.moveSpeed = stats.moveSpeed;
            this.stats.moveSpeedMult = 1.0;
            this.stats.jump = stats.jump;
            this.stats.weight = stats.weight;
            this.stats.movementType = stats.movementType;
            this.stats.shield = 0;
            this.stats.maxShield = 0;
        }

        this.visual.animState = AnimState.IDLE;
        this.visual.visualStatus = 'NONE';
        this.visual.hitFlashTimer = 0;
        this.visual.spawnTimer = 0.5;
        this.visual.trailHistory = [];
        this.visual.facing = this.team === Team.BLUE ? 1 : -1;

        this.status.stun = { timer: 0, max: 0 };
        this.status.banish = { timer: 0, max: 0, active: false };
        this.status.silence = { timer: 0, max: 0 };
        this.status.root = this.status.fear = this.status.taunt = this.status.blind = 0;
        this.status.dot = { timer: 0, dmg: 0 };
        this.status.hot = { timer: 0, val: 0 };
        this.status.drStacks = {};
        this.status.drTimers = {};

        this.skillIds = [...this.initialState.skillIds];
        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.path = [];
        this.moveProgress = 0;
        this.target = null;
        this.targetHex = null;
        this.fullyDead = false;
        this.deadLogged = false;

        this.refreshAssets();
    }
}

import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { FACTION_VISUALS } from "../../data/vfx/faction_visuals";

export class AgentManager {
    /**
     * 新增單位：支持強制職業注入
     */
    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number, forceRole?: Role): Agent | null {
        // 防止在地圖外或障礙物上生成
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);

        // 職業選擇：如果沒有強制指定，則隨機
        const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        a.role = forceRole || allRoles[Math.floor(Math.random() * allRoles.length)];

        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        // 元件初始化
        const stats = UNIT_DB[a.role];
        a.stats.maxHp = hpOverride || stats.maxHp;
        a.stats.hp = a.stats.maxHp;
        a.stats.maxMp = stats.maxMp;
        a.stats.moveSpeed = stats.moveSpeed; 
        a.stats.movementType = stats.movementType;
        a.stats.jump = stats.jump;
        a.stats.weight = stats.weight;

        // 技能匹配
        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rndS = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rndS(validSkills.filter(s => s.tag === 'ULT')),
            rndS(validSkills.filter(s => s.tag === 'ACTIVE')),
            rndS(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        const visual = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];
        a.visual.spawnTimer = 0.5;
        a.refreshAssets(); // 關鍵：ECS 資源掛載

        engine.events.push({ type: 'SPAWN', pos: { x: a.physics.px, y: a.physics.py }, color: visual.primaryColor, sourceId: a.id });

        if (engine.isRunning) {
            a.skills = a.skillIds.map(id => engine.skillDB.find(s => s.id === id) || null);
            a.bt = engine.ai.buildAI(a, engine);
            a.visual.animState = AnimState.IDLE;
        }

        engine.agents.push(a);
        engine.map.registerAgent(a);
        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;
        if (!a.deadLogged) {
            engine.log(a, 'DEATH', '死亡', null, '陣亡');
            engine.events.push({ type: 'DEATH', pos: {x: a.physics.px, y: a.physics.py}, sourceId: a.id, team: a.team });
            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);

            engine.map.unregisterAgent(a);

            a.fullyDead = true; 
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);

    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => engine.bus.off('GAME_OVER', handleGameOver);
    }, []);

    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    /** 核心優化：職業平衡生成器 (Balanced 5VS5) */
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        // 洗牌算法
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;

        const spawnTeam = (team: Team) => {
            roles.forEach(role => {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    const hp = 600 + Math.floor(Math.random() * 400); 
                    engine.addAgent(team, h.q, h.r, hp, role);
                }
            });
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);

        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    useEffect(() => {
        const interval = setInterval(() => setUnitCount(engineRef.current.agents.length), 500); 
        return () => clearInterval(interval);
    }, []);

    useEffect(() => { engineRef.current.timeScale = timeScale; }, [timeScale]);

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w); setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null); setWinner(null);
    }, []);

    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null); setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    /** 核心優化：隨機戰場亦套用職業平衡 */
    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null); setSelectedAgent(null);
        engine.clear(false); 

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w); setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIdx = 0;
        const spawnTeam = (team: Team) => {
            roles.forEach(role => {
                if (spawnIdx < validHexes.length) {
                    const h = validHexes[spawnIdx++];
                    engine.addAgent(team, h.q, h.r, 800, role);
                }
            });
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);
        setIsPlaying(false); 
    }, []);

    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => setSelectedAgent(a);

    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode, handleUpdateMapSize, handleUpdateLayout, handleSetScene,
            handleRandomBattlefield, handleNextLevel, handleReset, togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent, startShowcaseMatch, downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, GameEventType, AnimState, SceneTheme, Hex, MovementType, LogActionType, HexLayout } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { DEFAULT_HEX_LAYOUT } from "../constants";

import { Agent } from "./core/Agent";
import { MovementSystem } from "./systems/movement";
import { PhysicsSystem } from "./systems/PhysicsSystem"; 
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { HazardSystem } from "./systems/HazardSystem"; 
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { AnnouncerSystem } from "./systems/AnnouncerSystem"; 
import { DirectorSystem } from "./systems/DirectorSystem"; 
import { BattleLogger } from "./systems/BattleLogger"; 
import { TimeSystem } from "./systems/TimeSystem"; 
import { VictorySystem } from "./systems/VictorySystem"; 
import { ZoneSystem } from "./systems/ZoneSystem"; 
import { EventBus } from "./events/EventBus";

import { CooldownSystem } from "./systems/status/CooldownSystem";
import { EffectSystem } from "./systems/status/EffectSystem";
import { ControlSystem } from "./systems/status/ControlSystem";

import type { GameRenderer } from "./renderer";

export { Agent };

export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];

    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }
    get agentMap() { return this.map.agentMap; }
    get logs() { return this.logger.logs; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;
    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    get timeScale() { return this.time.timeScale; }
    set timeScale(v: number) { this.time.timeScale = v; }
    get targetTimeScale() { return this.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.time.targetTimeScale = v; }
    get battleTime() { return this.time.battleTime; }
    set battleTime(v: number) { this.time.battleTime = v; }

    get isFinishing() { return this.victory.isFinishing; }
    get victoryTimer() { return this.victory.victoryTimer; }
    get winningTeam() { return this.victory.winningTeam; }

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0, layout: DEFAULT_HEX_LAYOUT };
    public currentScene: SceneTheme = SCENE_DB[0];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public movement: MovementSystem;
    public physics: PhysicsSystem; 
    public combat: CombatSystem;
    public map: MapSystem;
    public hazards: HazardSystem;
    public ai: AISystem;
    public agentManager: AgentManager;
    public announcer: AnnouncerSystem; 
    public director: DirectorSystem;
    public logger: BattleLogger; 
    public time: TimeSystem; 
    public victory: VictorySystem; 
    public zones: ZoneSystem; 
    public cooldowns: CooldownSystem;
    public effects: EffectSystem;
    public controls: ControlSystem;

    get directorTargetId() { return this.director.targetId; }

    constructor() {
        this.movement = new MovementSystem();
        this.physics = new PhysicsSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.hazards = new HazardSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.announcer = new AnnouncerSystem(); 
        this.director = new DirectorSystem();
        this.logger = new BattleLogger();
        this.time = new TimeSystem();
        this.victory = new VictorySystem();
        this.zones = new ZoneSystem();
        this.cooldowns = new CooldownSystem();
        this.effects = new EffectSystem();
        this.controls = new ControlSystem();

        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number, forceRole?: Role) { return this.agentManager.addAgent(this, team, q, r, hpOverride, forceRole); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId: string | null = null, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    getAgentAt(q: number, r: number) { return this.map.getAgentAt(q, r); }
    removeAgent(q: number, r: number) { 
        const a = this.getAgentAt(q, r);
        if (a) {
            this.agents = this.agents.filter(x => x !== a);
            this.map.unregisterAgent(a);
        }
    }
    updateAgentPosition(agent: Agent, q: number, r: number) { this.map.updateAgentPosition(agent, q, r); }

    log(agent: Agent | null, type: LogActionType, action: string, target: string | null, detail: string) {
        this.logger.log(this.battleTime, 0, agent, type, action, target, detail);
    }

    play() { this.isRunning = true; }
    stop() { this.isRunning = false; }
    restart() {
        this.stop();
        this.battleTime = 0;
        this.time.reset();
        this.victory.reset();
        this.combat.reset();
        this.hazards.reset();
        this.announcer.reset();
        this.agents.forEach(a => a.reset(this.mapConfig));
        this.agents.forEach(a => {
            a.bt = this.ai.buildAI(a, this);
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
        });
        this.map.clearAgents();
        this.agents.forEach(a => this.map.registerAgent(a));
    }

    clear(resetMap: boolean = false) {
        this.stop();
        this.agents = [];
        this.combat.reset();
        this.hazards.reset();
        this.logger.clear();
        this.map.clearAgents();
        if (resetMap) {
            this.map.resetData();
            this.map.registerTile(0,0);
        }
    }

    randomizeEnvironment() {
        this.map.randomizeEnvironment(this);
    }

    tick(dt: number) {
        if (!this.isRunning) return;

        this.events = [];
        this.time.update(dt);

        this.victory.updateFinishing(dt, this);
        if (this.victory.check(this)) return;

        this.combat.update(dt, this);
        this.hazards.update(dt, this);
        this.announcer.update(dt, this);

        for (const a of this.agents) {
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            this.cooldowns.update(a, dt);
            this.effects.update(a, dt, this);
            this.controls.update(a, dt, this);

            if (a.bt && a.castingSkillIdx === -1 && a.stunTimer <= 0 && !a.banished) {
                a.bt.tick(a);
            }

            if (a.isMoving) {
                this.movement.updateMovement(a, dt, this);
            }
        }

        this.physics.update(dt, this);
        this.movement.resolveStacking(this);
        this.zones.update(this);
    }
}

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";
import { SpriteManager, UnitAssets } from "../sprites";

// --- ECS COMPONENTS ---

/** 物理組件：負責空間座標與動力學積算 */
export interface PhysicsComponent {
    x: number; y: number; z: number;
    vx: number; vy: number; vz: number;
    angle: number; vAngle: number;
    px: number; py: number; // 邏輯世界座標 (Logical Ground)
}

/** 視覺組件：負責美術資源、動畫狀態與殘影緩存 */
export interface VisualComponent {
    assets: UnitAssets | null;
    animState: AnimState;
    visualStatus: 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';
    facing: number;
    hitFlashTimer: number;
    spawnTimer: number;
    trailHistory: {x: number, y: number, z: number}[];
}

/** 數值組件：負責生命週期與戰鬥屬性 */
export interface StatsComponent {
    hp: number; maxHp: number;
    mp: number; maxMp: number;
    shield: number; maxShield: number;
    weight: number; jump: number;
    moveSpeed: number; moveSpeedMult: number;
    movementType: MovementType;
}

/** 狀態組件：負責 CC 效果與 DR 衰減 */
export interface StatusComponent {
    stun: { timer: number, max: number };
    banish: { timer: number, max: number, active: boolean };
    silence: { timer: number, max: number };
    root: number; fear: number; taunt: number; blind: number;
    tauntTargetId: string | null;
    dot: { timer: number, dmg: number };
    hot: { timer: number, val: number };
    drStacks: Record<string, number>;
    drTimers: Record<string, number>;
}

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;

    // ECS Components
    public physics: PhysicsComponent;
    public visual: VisualComponent;
    public stats: StatsComponent;
    public status: StatusComponent;

    // AI & Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public curCDs: number[] = [0, 0, 0];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    // Fix: Added castingAnimationTimer to handle visual cast timing independently
    public castingAnimationTimer: number = 0;

    public bt: BTNode | null = null;
    public btStatus: string = "待機";
    public target: Agent | null = null;
    public targetHex: Hex | null = null;
    public isMoving: boolean = false;
    public path: Hex[] = [];
    public trajectory: Hex[] = [];
    public moveProgress: number = 0;

    public fullyDead: boolean = false;
    public deadLogged: boolean = false;

    public initialState: any;

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR;
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);

        // 初始化物理組件 (Physics SSOT)
        this.physics = {
            x: 0, y: 0, z: 0,
            vx: 0, vy: 0, vz: 0,
            angle: 0, vAngle: 0,
            px: p.x, py: p.y
        };

        // 初始化視覺組件 (Visual ECS)
        this.visual = {
            assets: null,
            animState: AnimState.IDLE,
            visualStatus: 'NONE',
            facing: team === Team.BLUE ? 1 : -1,
            hitFlashTimer: 0,
            spawnTimer: 0.5,
            trailHistory: []
        };

        // 初始化數值組件
        this.stats = {
            hp: 100, maxHp: 100,
            mp: 0, maxMp: 100,
            shield: 0, maxShield: 0,
            weight: 1, jump: 1,
            moveSpeed: 1, moveSpeedMult: 1,
            movementType: MovementType.GROUND
        };

        // 初始化狀態組件
        this.status = {
            stun: { timer: 0, max: 0 },
            banish: { timer: 0, max: 0, active: false },
            silence: { timer: 0, max: 0 },
            root: 0, fear: 0, taunt: 0, blind: 0,
            tauntTargetId: null,
            dot: { timer: 0, dmg: 0 },
            hot: { timer: 0, val: 0 },
            drStacks: {},
            drTimers: {}
        };
    }

    /** 核心資源同步：按職業與陣營刷新 ECS 資源 */
    public refreshAssets() {
        this.visual.assets = SpriteManager.getUnitImages(this.role, this.team);
    }

    /** Legacy Compatibility Getters (避免大規模破壞系統) */
    get hp() { return this.stats.hp; }
    set hp(v) { this.stats.hp = v; }
    get maxHp() { return this.stats.maxHp; }
    set maxHp(v) { this.stats.maxHp = v; }
    get mp() { return this.stats.mp; }
    set mp(v) { this.stats.mp = v; }
    get maxMp() { return this.stats.maxMp; }
    set maxMp(v) { this.stats.maxMp = v; }
    get shield() { return this.stats.shield; }
    set shield(v) { this.stats.shield = v; }
    get maxShield() { return this.stats.maxShield; }
    set maxShield(v) { this.stats.maxShield = v; }
    get px() { return this.physics.px; }
    set px(v) { this.physics.px = v; }
    get py() { return this.physics.py; }
    set py(v) { this.physics.py = v; }
    get facing() { return this.visual.facing; }
    set facing(v) { this.visual.facing = v; }
    get animState() { return this.visual.animState; }
    set animState(v) { this.visual.animState = v; }
    get visualStatus() { return this.visual.visualStatus; }
    set visualStatus(v) { this.visual.visualStatus = v; }
    get hitFlashTimer() { return this.visual.hitFlashTimer; }
    set hitFlashTimer(v) { this.visual.hitFlashTimer = v; }
    get spawnTimer() { return this.visual.spawnTimer; }
    set spawnTimer(v) { this.visual.spawnTimer = v; }
    get jump() { return this.stats.jump; }
    set jump(v) { this.stats.jump = v; }
    get weight() { return this.stats.weight; }
    set weight(v) { this.stats.weight = v; }
    get moveSpeed() { return this.stats.moveSpeed; }
    set moveSpeed(v) { this.stats.moveSpeed = v; }
    get moveSpeedMult() { return this.stats.moveSpeedMult; }
    set moveSpeedMult(v) { this.stats.moveSpeedMult = v; }
    get movementType() { return this.stats.movementType; }
    set movementType(v) { this.stats.movementType = v; }
    get trailHistory() { return this.visual.trailHistory; }
    set trailHistory(v) { this.visual.trailHistory = v; }

    /** 改良型狀態計時器訪問器 */
    get stunTimer() { return this.status.stun.timer; }
    set stunTimer(v) { this.status.stun.timer = v; }
    get stunMax() { return this.status.stun.max; }
    set stunMax(v) { this.status.stun.max = v; }
    get banishTimer() { return this.status.banish.timer; }
    set banishTimer(v) { this.status.banish.timer = v; }
    get banishMax() { return this.status.banish.max; }
    set banishMax(v) { this.status.banish.max = v; }
    get banished() { return this.status.banish.active; }
    set banished(v) { this.status.banish.active = v; }
    get silenceTimer() { return this.status.silence.timer; }
    set silenceTimer(v) { this.status.silence.timer = v; }
    get silenceMax() { return this.status.silence.max; }
    set silenceMax(v) { this.status.silence.max = v; }
    get rootTimer() { return this.status.root; }
    set rootTimer(v) { this.status.root = v; }
    get fearTimer() { return this.status.fear; }
    set fearTimer(v) { this.status.fear = v; }
    get tauntTimer() { return this.status.taunt; }
    set tauntTimer(v) { this.status.taunt = v; }
    get blindTimer() { return this.status.blind; }
    set blindTimer(v) { this.status.blind = v; }
    get tauntTargetId() { return this.status.tauntTargetId; }
    set tauntTargetId(v) { this.status.tauntTargetId = v; }
    get dotTimer() { return this.status.dot.timer; }
    set dotTimer(v) { this.status.dot.timer = v; }
    get dotDmg() { return this.status.dot.dmg; }
    set dotDmg(v) { this.status.dot.dmg = v; }
    get hotTimer() { return this.status.hot.timer; }
    set hotTimer(v) { this.status.hot.timer = v; }
    get hotVal() { return this.status.hot.val; }
    set hotVal(v) { this.status.hot.val = v; }
    get drStacks() { return this.status.drStacks; }
    get drTimers() { return this.status.drTimers; }

    public setAnim(state: AnimState) {
        if (this.visual.animState !== state && this.visual.animState !== AnimState.DEAD) {
            this.visual.animState = state;
        }
    }

    public saveState() {
        this.initialState = {
            q: this.q, r: this.r,
            maxHp: this.stats.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    public reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);

        this.physics.px = p.x;
        this.physics.py = p.y;
        this.physics.x = this.physics.y = this.physics.z = 0;
        this.physics.vx = this.physics.vy = this.physics.vz = 0;
        this.physics.angle = this.physics.vAngle = 0;

        this.role = this.initialState.role;
        const stats = UNIT_DB[this.role];
        if (stats) {
            this.stats.maxHp = this.initialState.maxHp;
            this.stats.hp = this.stats.maxHp;
            this.stats.mp = 0;
            this.stats.maxMp = stats.maxMp;
            this.stats.moveSpeed = stats.moveSpeed;
            this.stats.moveSpeedMult = 1.0;
            this.stats.jump = stats.jump;
            this.stats.weight = stats.weight;
            this.stats.movementType = stats.movementType;
            this.stats.shield = 0;
            this.stats.maxShield = 0;
        }

        this.visual.animState = AnimState.IDLE;
        this.visual.visualStatus = 'NONE';
        this.visual.hitFlashTimer = 0;
        this.visual.spawnTimer = 0.5;
        this.visual.trailHistory = [];
        this.visual.facing = this.team === Team.BLUE ? 1 : -1;

        this.status.stun = { timer: 0, max: 0 };
        this.status.banish = { timer: 0, max: 0, active: false };
        this.status.silence = { timer: 0, max: 0 };
        this.status.root = this.status.fear = this.status.taunt = this.status.blind = 0;
        this.status.dot = { timer: 0, dmg: 0 };
        this.status.hot = { timer: 0, val: 0 };
        this.status.drStacks = {};
        this.status.drTimers = {};

        this.skillIds = [...this.initialState.skillIds];
        this.castingSkillIdx = -1;
        this.castTimer = 0;
        // Fix: Reset castingAnimationTimer during reset
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.path = [];
        this.moveProgress = 0;
        this.target = null;
        this.targetHex = null;
        this.fullyDead = false;
        this.deadLogged = false;

        this.refreshAssets();
    }
}
